import json
with open('/app/resources/treasury_bulletin_1947_02.json', 'r') as f:
    data = json.load(f)

# Print the structure
def print_structure(d, indent=0):
    if isinstance(d, dict):
        for k, v in d.items():
            print('  ' * indent + str(k))
            if isinstance(v, (dict, list)):
                print_structure(v, indent + 1)
    elif isinstance(d, list) and len(d) > 0:
        print('  ' * indent + f'List[{len(d)}]')
        if isinstance(d[0], dict):
            print('  ' * indent + 'First item keys:')
            for k in d[0].keys():
                print('  ' * (indent+1) + str(k))

print_structure(data)
